ALTER TABLE "leagues" ADD COLUMN "seasonConfig" jsonb DEFAULT '{}' NOT NULL;--> statement-breakpoint
UPDATE "leagues" SET "seasonConfig" = "latest"."config" - 'goalTypes' FROM (SELECT DISTINCT ON ("leagueUuid") "leagueUuid", "config" FROM "seasons" WHERE "$deletedAt" IS NULL ORDER BY "leagueUuid", "startDate" DESC) AS "latest" WHERE "latest"."leagueUuid" = "leagues"."uuid";--> statement-breakpoint
